begin;
delete from obstacle_feature where place_name like '[GOODROAD_OSM_SEED]%';

create temporary table tmp_goodroad_osm_seed (
    source_key varchar(96) primary key,
    type varchar(32) not null,
    latitude double precision not null,
    longitude double precision not null,
    country varchar(120) not null,
    region varchar(120) not null,
    locality_type varchar(80) not null,
    city varchar(120) not null,
    street varchar(120) not null,
    house varchar(40) not null,
    place_name varchar(180) not null,
    severity_estimate smallint not null
) on commit drop;


    type, latitude, longitude, country, region, locality_type, city,
    street, house, place_name, severity_estimate, reviews_count, last_reviewed_at
)
select type, latitude, longitude, country, region, locality_type, city,
       street, house, place_name, severity_estimate, 0, null
from tmp_goodroad_osm_seed;

    feature_id, obstacle_type, severity_estimate, reviews_count
)
select f.id, s.type, s.severity_estimate, 0
from tmp_goodroad_osm_seed s
join obstacle_feature f
  on f.type = s.type
 and f.country = s.country
 and f.region = s.region
 and f.locality_type = s.locality_type
 and f.city = s.city
 and f.street = s.street
 and f.house = s.house
 and coalesce(f.place_name, '') = s.place_name
on conflict (feature_id, obstacle_type) do nothing;

commit;
